def sql(q):
    return subprocess.run(["psql","-h","localhost","-U","jm","-d","jm_app","-AtF","|","-c",q], env={**os.environ,"PGPASSWORD":"jm"}, capture_output=True, text=True).stdout.strip()
def check(name, ok, detail=""):
    RES.append((name, bool(ok))); print(("  PASS  " if ok else "  FAIL  ")+name+(f"   [{detail}]" if detail and not ok else (f"   ({detail})" if detail else "")), flush=True)

def publish(page): page.get_by_role("button", name=re.compile("E.lon qilish|Yangilash")).click(); page.wait_for_url(re.compile(r"/admin\?saqlandi"), timeout=60000)
